      [ { q: '흥부가 박을 탔을 때 벌어진 일과, 큰 부자가 된 뒤에도 변치 않은 흥부의 모습을 본문을 근거로 쓰세요.',
          a: '박을 타자 쌀과 돈, 금은보화와 비단, 기와집을 짓는 목수까지 쏟아져 나와 흥부네는 하루아침에 큰 부자가 되었다. 그러나 흥부는 교만하지 않고 어려운 이웃에게 재물을 아낌없이 나누며, 착하고 어진 마음을 끝내 잃지 않았다.' } ],
