      [ { q: '허생이 변씨에게 돈을 빌리는 장면과, 변씨가 선뜻 만 냥을 내준 까닭을 본문을 근거로 쓰세요.',
          a: '허생은 처음 보는 변씨에게 절하고 대뜸 만 냥을 꾸어 달라 했고, 변씨는 두말없이 내주었다. 변씨는 "구하는 자는 으레 큰소리로 떠벌리는데, 저 사람은 행색은 초라해도 말이 간단하고 당당해 예사 인물이 아니라" 여겼기 때문이다.' } ],
      [ { q: '허생이 안성에서 벌인 일과 그 결과, 그리고 그가 한 한탄의 뜻을 본문을 근거로 쓰세요.',
          a: '허생은 안성에서 과일을 두 배 값에 몽땅 사들여 나라 안 과일이 동나자, 열 배로 되팔아 큰돈을 벌었다. 그러나 "겨우 만 냥으로 온 나라 과일을 좌지우지할 수 있다니, 나라 경제의 밑천이 그만큼 보잘것없다"며 조선 경제의 허약함을 탄식했다.' } ],
      [ { q: '허생이 제주에서 말총을 사들여 일어난 일은 무엇이며, 그가 거듭 한탄한 까닭은 무엇인지 본문을 근거로 쓰세요.',
          a: '허생이 망건·갓의 재료인 말총을 모조리 사들이자 재료가 동나 망건값이 열 배로 뛰었다. 한 사람의 매점만으로 온 나라 물가가 요동치고 백성이 곤란을 겪는 것을 보며, 나라 경제가 그토록 허약함을 뼈아프게 곱씹으며 한탄했다.' } ],
      [ { q: '허생이 변산의 도적 떼를 어떻게 다루었으며, 그 결과 도적들의 삶은 어떻게 달라졌는지 본문을 근거로 쓰세요.',
          a: '허생은 도적 소굴로 들어가 그들의 딱한 처지를 헤아려, 백 냥씩과 여자·소를 마련하게 한 뒤 빈 섬으로 데려가 농사짓게 했다. 칼로 빼앗던 자들이 괭이로 제 땅을 일구며, 도적들은 비로소 사람다운 삶을 되찾았다.' } ],
      [ { q: '섬에서 큰 재물을 번 허생이 보인 뜻밖의 행동들과, 거기에 담긴 그의 생각을 본문을 근거로 쓰세요.',
          a: '허생은 곡식을 일본에 팔아 은 백만 냥을 벌고도 기뻐하지 않고, "작은 섬에 많은 재물을 쌓으면 화가 된다"며 오십만 냥을 바다에 던졌다. 글 아는 자는 분란의 씨가 될까 데리고 나왔으며, 재물도 임금 자리도 미련 없이 버렸다.' } ],
      [ { q: '허생이 변씨에게 빌린 돈을 갚는 장면에서 드러나는 허생의 성품은 어떠한지 본문을 근거로 쓰세요.',
          a: '허생은 가난한 백성에게 돈과 곡식을 베풀고도 남은 십만 냥을, 빌린 만 냥의 열 배로 변씨에게 갚았다. 사양하는 변씨에게 "나를 장사치로 보느냐"며 굳이 돈을 두고 가는 데서, 재물에 집착하지 않는 호방하고 대범한 성품이 드러난다.' } ],
      [ { q: '이완 대장에게 허생이 내놓은 세 가지 계책은 무엇이며, 이완은 그에 대해 어떤 태도를 보였는지 본문을 근거로 쓰세요.',
          a: '허생은 ①숨은 인재를 삼고초려로 모실 것 ②명나라 사람들에게 권세가의 딸을 시집보내고 벼슬·집을 줄 것 ③젊은이를 청에 보내 실정을 익히게 할 것을 제안했다. 그러나 이완은 번번이 "사대부 체면에 어렵다"며 낡은 체면만 내세워 난색을 표했다.' } ],
      [ { q: '세 계책이 거절당한 뒤 허생의 반응과 결말은 어떠했으며, 이를 통해 작가가 비판하려 한 것은 무엇인지 본문을 근거로 쓰세요.',
          a: '허생은 말로만 북벌을 외치며 아무것도 실천 않는 사대부를 꾸짖고 칼을 들어 이완을 내쫓았으며, 이튿날 홀연 자취를 감췄다. 작가는 말뿐인 무능한 사대부와, 큰 인재를 쓰지 못하는 현실을 날카롭게 비판한 것이다.' } ]
