      [ { q: '곽씨 부인이 죽은 뒤 심 봉사가 어린 심청을 어떻게 키웠는지 본문을 근거로 쓰세요.',
          a: '곽씨 부인은 심청을 낳은 지 이레 만에 아이를 잘 길러 달라는 유언을 남기고 죽었다. 심 봉사는 통곡하면서도 젖먹이를 살리려 동네 아낙들을 찾아 젖동냥을 하고, 모자라면 미음을 쑤어 먹이며 밤을 지새워 홀로 딸을 키웠다.' } ],
      [ { q: '자란 심청은 눈먼 아버지를 어떻게 봉양했으며, 그 모습에 대한 주변의 반응은 어떠했는지 본문을 근거로 쓰세요.',
          a: '심청은 어려서부터 철이 들어 동냥과 품팔이로 아버지를 봉양하고, 추운 날엔 언 손을 녹이고 따뜻한 밥을 먼저 올렸다. 맛난 것이 생기면 저는 굶어도 아버지께 드렸으며, 동네 사람들은 그 효성을 입을 모아 칭찬했다.' } ],
