      [ { q: '연꽃에서 나온 심청이 황후가 된 과정과, 황후가 되고도 심청이 품은 근심 및 그 해결책을 본문을 근거로 쓰세요.',
          a: '상인들이 바친 연꽃에서 나온 심청을, 황후를 잃고 지내던 임금이 감복해 황후로 맞았다. 그러나 심청은 홀로 둔 눈먼 아버지가 눈을 떴는지 살아 계신지 몰라 애태우다, 아버지를 찾으려 온 나라 맹인을 부르는 잔치를 열기로 했다.' } ],
